select 'refdata_ir_curve_bootstrap_configs (overnight-index)' as entity, count(*) as count
from ores_refdata_ir_curve_bootstrap_configs_tbl
where tenant_id = ores_utility_system_tenant_id_fn()
  and name in ('EUR-ESTR', 'GBP-SONIA', 'JPY-TONA', 'CHF-SARON', 'AUD-AONIA', 'CAD-CORRA', 'NZD-NZONIA', 'CLP-CAMARA', 'COP-IBR', 'CZK-CZEONIA', 'DKK-DESTR', 'HKD-HONIA', 'INR-MIBOR', 'KRW-KOFR', 'MXN-TIIE', 'SEK-SWESTR', 'SGD-SORA', 'TRY-TLREF', 'ZAR-ZARONIA')
